2: import 'package:mad_flutter_practicum/domain/datasource/rest_datasource.dart';
3: import 'package:mad_flutter_practicum/domain/model/news_filter.dart';
4: import 'package:mad_flutter_practicum/domain/model/news_model.dart';
5: import 'package:mad_flutter_practicum/domain/repository/news_repository.dart';
6: 
7: class NewsRepositoryImpl implements NewsRepository {
8:   const NewsRepositoryImpl(this._restDatasource, this._dbDatasource);
9: 
10:   final RestDatasource _restDatasource;
11:   final DbDatasource _dbDatasource;
12: 
13:   @override
14:   @Deprecated('v2: используйте loadNewsFeed; будет удалено в v3')
15:   Future<List<NewsModel>> getNewsList() => _restDatasource.getNewsList();
16: 
17:   @override
18:   Future<List<NewsModel>> loadNewsFeed(NewsFeedFilter filter) async {
19:     if (filter.forceRefresh) {
20:       final List<NewsModel> fresh = await _restDatasource.getNewsList();
21:       await _dbDatasource.saveNewsList(fresh);
22:       return fresh;
23:     }
24:     return _dbDatasource.getNewsList();
25:   }
26: 
27:   @override
28:   Stream<NewsFeed> watchNewsFeed(NewsFeedFilter filter) async* {
29:     final List<NewsModel> cached = await _dbDatasource.getNewsList();
30: 
31:     if (cached.isNotEmpty) {
32:       yield NewsFeed(items: cached, source: NewsFeedSource.cache);
33:     }
34: 
35:     try {
36:       final List<NewsModel> fresh = await _restDatasource.getNewsList();
37:       await _dbDatasource.saveNewsList(fresh);
38:       yield NewsFeed(items: fresh, source: NewsFeedSource.network);
39:     } on Object {
40:       if (cached.isEmpty) rethrow;
41:     }
42:   }
43: 
44:   @override
45:   Future<void> saveNewsList(List<NewsModel> value) => _dbDatasource.saveNewsList(value);
46: }

1: import 'dart:async';
2: 
3: import 'package:mad_flutter_practicum/app/app.dart';
4: import 'package:mad_flutter_practicum/domain/domain.dart';
5: 
6: import 'widgets/widgets.dart';
7: 
8: class NewsListPage extends StatefulWidget {
9:   const NewsListPage({super.key});
10: 
11:   @override
12:   State<NewsListPage> createState() => _NewsListPageState();
13: }
14: 
15: class _NewsListPageState extends State<NewsListPage> with SingleTickerProviderStateMixin {
16:   static final _tween = Tween<double>(begin: 0.25, end: 1);
17: 
18:   late final AnimationController _scaleController;
19:   late final Animation<double> _scaleAnimation;
20: 
21:   StreamSubscription<NewsFeed>? _subscription;
22: 
23:   List<NewsModel> _newsList = const [];
24: 
25:   @override
26:   void initState() {
27:     super.initState();
28:     _initAnimation();
29:     _initData();
30:   }
31: 
32:   @override
33:   void dispose() {
34:     _subscription?.cancel();
35:     _scaleController.dispose();
36:     super.dispose();
37:   }
38: 
39:   void _initAnimation() {
40:     _scaleController = AnimationController(
41:       vsync: this,
42:       duration: Duration(milliseconds: 200),
43:     );
44:     _scaleAnimation = _tween.animate(_scaleController);
45:   }
46: 
47:   /// Cache-then-network: сначала мгновенно показываем кэш ленты,
48:   /// затем обновляем список, когда из сети придёт ответ.
49:   void _initData() {
50:     final newsRepository = context.read<NewsRepository>();
51: 
52:     _subscription = newsRepository.watchNewsFeed(const NewsFeedFilter()).listen(
53:       (NewsFeed feed) {
54:         if (!mounted) return;
55: 
56:         setState(() => _newsList = feed.items);
57: 
58:         if (feed.source == NewsFeedSource.network) {
59:           _scaleController.forward(from: 0); // запускаем анимацию
60:         }
61:       },
62:       onError: (Object _) {
63:         if (!mounted) return;
64: 
65:         _scaleController.forward(from: 0); // анимация для данных из кэша
66:       },
67:     );
68:   }
69: 
70:   @override
71:   Widget build(BuildContext context) {
72:     return Scaffold(
73:       appBar: AppBar(title: Text(context.loc.news)),
74:       body: _buildBody(),
75:     );
76:   }
77: 
78:   Widget _buildBody() {
79:     if (_newsList.isEmpty) return const SizedBox.shrink();
80: 
81:     return ScaleTransition(
82:       scale: _scaleAnimation,
83:       child: ListView.builder(
84:         itemCount: _newsList.length,
85:         itemBuilder: (BuildContext context, int index) {
86:           final NewsModel news = _newsList[index];
87: 
88:           return Padding(
89:             key: ValueKey(news.link),
90:             padding: index == 0 ? EdgeInsets.zero : const EdgeInsets.only(top: 16),
91:             child: NewsCard(model: news),
92:           );
93:         },
94:         padding: const EdgeInsets.fromLTRB(22, 16, 22, 40),
95:       ),
96:     );
97:   }
98: }
